use clap::Parser;
use std::io::{self, BufRead};

mod parser;
mod query;
mod operators;
mod types;
mod output;
mod filter;
mod aggregator;

use query::Query;

#[derive(Parser, Debug)]
#[command(name = "ag")]
#[command(version = "0.19.6")]
#[command(about = "Angle grinder - log analysis tool", long_about = None)]
struct Args {
    /// The query to execute
    query: Option<String>,

    /// Read from file instead of stdin
    #[arg(short, long)]
    file: Option<String>,

    /// Output format (json, logfmt, format=<rust format string>, legacy)
    #[arg(short, long)]
    output: Option<String>,

    /// DEPRECATED. Use -o format=... instead
    #[arg(short, long)]
    format: Option<String>,

    /// Specifies an alternative directory for aliases
    #[arg(short = 'a', long)]
    alias_dir: Option<String>,

    /// Disables aliases
    #[arg(long)]
    no_alias: bool,
}

fn main() -> anyhow::Result<()> {
    let args = Args::parse();

    let query_string = args.query.as_ref().ok_or_else(|| {
        anyhow::anyhow!("Query string required")
    })?;

    let query = Query::parse(query_string)?;

    let mut output_format = args.output.clone();
    if output_format.is_none() && args.format.is_some() {
        output_format = args.format;
    }

    let reader: Box<dyn BufRead> = if let Some(file_path) = &args.file {
        Box::new(io::BufReader::new(std::fs::File::open(file_path)?))
    } else {
        Box::new(io::BufReader::new(io::stdin()))
    };

    query.execute(reader, output_format.as_deref())?;

    Ok(())
}
