use regex::Regex;

#[derive(Debug, Clone)]
pub enum Filter {
    All,
    MatchAny(String),
    MatchExact(String),
    And(Box<Filter>, Box<Filter>),
    Or(Box<Filter>, Box<Filter>),
    Not(Box<Filter>),
}

impl Filter {
    pub fn matches(&self, line: &str) -> bool {
        match self {
            Filter::All => true,
            Filter::MatchAny(pattern) => {
                let re = Regex::new(&format!("(?i){}",
                    regex::escape(pattern).replace("\\*", ".*")))
                    .unwrap_or_else(|_| Regex::new(".*").unwrap());
                re.is_match(line)
            }
            Filter::MatchExact(exact) => line.contains(exact),
            Filter::And(left, right) => left.matches(line) && right.matches(line),
            Filter::Or(left, right) => left.matches(line) || right.matches(line),
            Filter::Not(f) => !f.matches(line),
        }
    }
}

pub fn parse_filters(filters: &str) -> anyhow::Result<Filter> {
    // Simple filter parser - handles wildcards and exact matches
    if filters.trim() == "*" {
        return Ok(Filter::All);
    }

    // For now, just handle simple cases
    if filters.contains('"') {
        let exact = filters.trim_matches('"');
        Ok(Filter::MatchExact(exact.to_string()))
    } else {
        Ok(Filter::MatchAny(filters.to_string()))
    }
}
EOF

