use crate::types::{Row, Value};
use std::collections::BTreeMap;

#[derive(Debug, Clone)]
pub enum OperatorType {
    Json { from_field: Option<String> },
    Logfmt,
    Parse {
        pattern: String,
        fields: Vec<String>,
    },
    Fields {
        fields: Vec<String>,
    },
    Where {
        condition: String,
    },
}

impl OperatorType {
