            }
            AggregationOp::CountDistinct { as_name, .. } => as_name.clone().unwrap_or_else(|| "_count_distinct".to_string()),
        }
    }
}

#[derive(Clone, Debug)]
pub struct AggregationState {
    pub sum: f64,
    pub count: u64,
    pub min: Option<f64>,
    pub max: Option<f64>,
    pub values: Vec<f64>,
    pub distinct: std::collections::HashSet<String>,
}

impl AggregationState {
    pub fn new() -> Self {
        AggregationState {
            sum: 0.0,
            count: 0,
            min: None,
            max: None,
            values: Vec::new(),
            distinct: std::collections::HashSet::new(),
        }
    }

    pub fn update(&mut self, value: Option<f64>, distinct_val: Option<String>) {
        if let Some(v) = value {
            self.sum += v;
            self.count += 1;
            self.values.push(v);
            self.min = Some(self.min.map(|m| m.min(v)).unwrap_or(v));
            self.max = Some(self.max.map(m| m.max(v)).unwrap_or(v));
        }
        if let Some(v) = distinct_val {
            self.distinct.insert(v);
        }
    }

    pub fn compute(&self, op: &AggregationOp) -> Value {
        match op {
            AggregationOp::Count { .. } => Value::Number(self.count as f64),
            AggregationOp::Sum { .. } => Value::Number(self.sum),
            AggregationOp::Average { .. } => {
                if self.count > 0 {
                    Value::Number(self.sum / self.count as f64)
                } else {
                    Value::Number(0.0)
                }
            }
            AggregationOp::Min { .. } => {
                self.min.map(Value::Number).unwrap_or(Value::Null)
            }
            AggregationOp::Max { .. } => {
                self.max.map(Value::Number).unwrap_or(Value::Null)
            }
            AggregationOp::Percentile { percentile, .. } => {
                let mut sorted = self.values.clone();
                sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
                if sorted.is_empty() {
                    Value::Null
                } else {
                    let idx = ((*percentile as f64 / 100.0) * sorted.len() as f64) as usize;
                    let idx = idx.saturating_sub(1).min(sorted.len() - 1);
                    Value::Number(sorted[idx])
                }
            }
            AggregationOp::CountDistinct { .. } => {
                Value::Number(self.distinct.len() as f64)
            }
        }
    }
}

