use std::io::{self, BufRead};
use std::env;
use std::collections::BTreeMap;

mod types;
mod query;
mod operators;
mod filter;
mod aggregator;
mod output;

use query::Query;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        eprintln!("Usage: ag [OPTIONS] [QUERY]");
        std::process::exit(1);
    }

    let mut query_str = None;
    let mut file_path = None;
    let mut output_format = None;
    let mut i = 1;

    while i < args.len() {
        match args[i].as_str() {
            "-f" | "--file" => {
                if i + 1 < args.len() {
                    file_path = Some(args[i + 1].clone());
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-o" | "--output" => {
                if i + 1 < args.len() {
                    output_format = Some(args[i + 1].clone());
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-m" | "--format" => {
                if i + 1 < args.len() {
                    output_format = Some(format!("format={}", args[i + 1]));
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-a" | "--alias-dir" => {
                if i + 1 < args.len() {
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "--no-alias" => {
                i += 1;
            }
            "-h" | "--help" => {
                println!("Usage: ag [OPTIONS] [QUERY]\n\nOptions:\n  -f, --file <FILE>                 Read from file\n  -o, --output <OUTPUT>              Output format\n  -m, --format <FORMAT>              DEPRECATED. Use -o\n  -a, --alias-dir <ALIAS_DIR>        Alias directory\n  --no-alias                         Disable aliases\n  -h, --help                         Print help\n  -V, --version                      Print version");
                std::process::exit(0);
            }
            "-V" | "--version" => {
                println!("ag 0.19.6");
                std::process::exit(0);
            }
            other => {
                if !other.starts_with('-') {
                    query_str = Some(other.to_string());
                }
                i += 1;
            }
        }
    }

    let query_string = query_str.ok_or("Query string required")?;
