cat > /workspace/src/output.rs << 'EOF'
use crate::types::{Row, Value};
use std::collections::BTreeMap;
use std::io::Write;

pub struct OutputFormatter {
    format: OutputFormat,
}

enum OutputFormat {
    Legacy,
    Json,
    Logfmt,
    Format(String),
}

impl OutputFormatter {
    pub fn new(format: Option<&str>) -> Self {
        let output_format = match format {
            Some(f) if f.starts_with("format=") => {
                let fmt = f.strip_prefix("format=").unwrap_or("");
                OutputFormat::Format(fmt.to_string())
            }
            Some("json") => OutputFormat::Json,
            Some("logfmt") => OutputFormat::Logfmt,
            Some("legacy") => OutputFormat::Legacy,
            _ => OutputFormat::Legacy,
        };

        OutputFormatter {
            format: output_format,
        }
    }

    pub fn output_row(&self, row: &Row) -> Result<(), String> {
        let stdout = std::io::stdout();
        let mut handle = stdout.lock();

        match &self.format {
            OutputFormat::Legacy => {
                let mut output = String::new();
                for (key, value) in row {
                    if key != "_raw" {
                        output.push_str(&format!("[{}={}] ", key, value));
                    }
                }
                if !output.is_empty() {
                    writeln!(handle, "{}", output).map_err(|e| e.to_string())?;
                }
            }
            OutputFormat::Json => {
                let json_value = row_to_json(row);
                writeln!(handle, "{}", json_value).map_err(|e| e.to_string())?;
            }
            OutputFormat::Logfmt => {
                let mut output = String::new();
                for (key, value) in row {
                    if key != "_raw" {
                        output.push_str(&format!("{}={} ", key, value));
                    }
                }
                if !output.is_empty() {
                    writeln!(handle, "{}", output.trim()).map_err(|e| e.to_string())?;
                }
            }
            OutputFormat::Format(fmt) => {
                let formatted = format_row(row, fmt);
                writeln!(handle, "{}", formatted).map_err(|e| e.to_string())?;
            }
        }

        Ok(())
    }

    pub fn output_rows(&self, rows: &[Row]) -> Result<(), String> {
        let stdout = std::io::stdout();
        let mut handle = stdout.lock();

        match &self.format {
            OutputFormat::Legacy => {
                print_table(&mut handle, rows)?;
            }
            OutputFormat::Json => {
                let mut json_rows = Vec::new();
                for row in rows {
                    json_rows.push(row_to_json(row));
                }
                let output = format!("[{}]", json_rows.join(","));
                writeln!(handle, "{}", output).map_err(|e| e.to_string())?;
            }
            OutputFormat::Logfmt => {
                for row in rows {
                    let mut output = String::new();
                    for (key, value) in row {
                        if key != "_raw" && key != "_group" {
                            output.push_str(&format!("{}={} ", key, value));
                        }
                    }
                    if !output.is_empty() {
                        writeln!(handle, "{}", output.trim()).map_err(|e| e.to_string())?;
                    }
                }
            }
            OutputFormat::Format(fmt) => {
                for row in rows {
                    let formatted = format_row(row, fmt);
                    writeln!(handle, "{}", formatted).map_err(|e| e.to_string())?;
                }
            }
        }

        Ok(())
    }
}

fn print_table(handle: &mut std::io::StdoutLock, rows: &[Row]) -> Result<(), String> {
    if rows.is_empty() {
        return Ok(());
    }

    let mut all_keys = Vec::new();
    for row in rows {
        for key in row.keys() {
            if !all_keys.contains(key) && key != "_raw" && key != "_group" {
                all_keys.push(key.clone());
            }
        }
    }

    let mut column_widths: BTreeMap<String, usize> = BTreeMap::new();
    for key in &all_keys {
        column_widths.insert(key.clone(), key.len());
    }

    for row in rows {
        for key in &all_keys {
            let value = row.get(key).map(|v| v.to_string()).unwrap_or_default();
            let width = column_widths.get(key).copied().unwrap_or(0);
            column_widths.insert(key.clone(), width.max(value.len()));
        }
    }

    // Print header
    let mut header = String::new();
    for key in &all_keys {
        let width = column_widths.get(key).copied().unwrap_or(0);
        header.push_str(&format!("{:width$}", key, width = width));
        header.push_str("        ");
    }
    writeln!(handle, "{}", header.trim_end()).map_err(|e| e.to_string())?;

    // Print separator
    let mut separator = String::new();
    for key in &all_keys {
        let width = column_widths.get(key).copied().unwrap_or(0);
        separator.push_str(&"-".repeat(width));
