use std::collections::BTreeMap;
use std::fmt;

#[derive(Debug, Clone, PartialEq, PartialOrd)]
pub enum Value {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Value>),
    Object(BTreeMap<String, Value>),
}

impl Eq for Value {}

impl std::hash::Hash for Value {
    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
        match self {
            Value::Null => {
                0u8.hash(state);
            }
            Value::Bool(b) => {
                1u8.hash(state);
                b.hash(state);
            }
            Value::Number(n) => {
                2u8.hash(state);
                n.to_bits().hash(state);
            }
            Value::String(s) => {
                3u8.hash(state);
                s.hash(state);
            }
            Value::Array(_) => {
                4u8.hash(state);
            }
            Value::Object(_) => {
                5u8.hash(state);
            }
        }
    }
}

impl Value {
    pub fn as_f64(&self) -> Option<f64> {
        match self {
            Value::Number(n) => Some(*n),
            Value::String(s) => s.parse::<f64>().ok(),
            _ => None,
        }
    }

    pub fn as_str(&self) -> Option<&str> {
        match self {
            Value::String(s) => Some(s),
            _ => None,
        }
    }

    pub fn as_bool(&self) -> Option<bool> {
        match self {
            Value::Bool(b) => Some(*b),
            _ => None,
        }
    }

    pub fn is_null(&self) -> bool {
        matches!(self, Value::Null)
    }

    pub fn get(&self, key: &str) -> Option<&Value> {
        match self {
            Value::Object(map) => map.get(key),
            _ => None,
        }
    }

    pub fn index(&self, idx: usize) -> Option<&Value> {
        match self {
            Value::Array(arr) => arr.get(idx),
            _ => None,
        }
    }
}

impl fmt::Display for Value {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Value::Null => write!(f, "null"),
            Value::Bool(b) => write!(f, "{}", b),
            Value::Number(n) => {
                if n.fract() == 0.0 {
                    write!(f, "{}", *n as i64)
                } else {
                    write!(f, "{}", n)
                }
            }
            Value::String(s) => write!(f, "{}", s),
            Value::Array(_) => write!(f, "[array]"),
            Value::Object(_) => write!(f, "[object]"),
        }
    }
}

impl Ord for Value {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        match (self, other) {
            (Value::Number(a), Value::Number(b)) => {
                a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal)
            }
            (Value::String(a), Value::String(b)) => a.cmp(b),
            (Value::Bool(a), Value::Bool(b)) => a.cmp(b),
            (Value::Null, Value::Null) => std::cmp::Ordering::Equal,
            _ => std::cmp::Ordering::Equal,
        }
    }
}

pub type Row = BTreeMap<String, Value>;

#[derive(Debug, Clone)]
pub struct AggregatedRow {
    pub grouping_keys: Vec<(String, Value)>,
    pub aggregations: Vec<(String, Value)>,
}

// Minimal JSON parser
pub mod simple_json {
    use std::collections::BTreeMap;
    use super::Value;

    pub fn parse(s: &str) -> Result<Value, String> {
        let mut chars = s.chars().peekable();
        skip_whitespace(&mut chars);
        parse_value(&mut chars)
    }

    fn skip_whitespace(chars: &mut std::iter::Peekable<std::str::Chars>) {
        while let Some(&ch) = chars.peek() {
            if ch.is_whitespace() {
                chars.next();
            } else {
                break;
            }
        }
    }

    fn parse_value(chars: &mut std::iter::Peekable<std::str::Chars>) -> Result<Value, String> {
        skip_whitespace(chars);
        match chars.peek() {
            Some(&'{') => parse_object(chars),
            Some(&'[') => parse_array(chars),
            Some(&'"') => parse_string(chars).map(Value::String),
            Some(&'t') | Some(&'f') => parse_bool(chars),
            Some(&'n') => parse_null(chars),
            Some(&c) if c == '-' || c.is_numeric() => parse_number(chars),
            _ => Err("Unexpected character".to_string()),
        }
    }

    fn parse_object(chars: &mut std::iter::Peekable<std::str::Chars>) -> Result<Value, String> {
        chars.next(); // consume '{'
        let mut map = BTreeMap::new();
        skip_whitespace(chars);

        if chars.peek() == Some(&'}') {
            chars.next();
            return Ok(Value::Object(map));
        }

        loop {
            skip_whitespace(chars);
            let key = parse_string(chars)?;
            skip_whitespace(chars);
            if chars.next() != Some(':') {
                return Err("Expected ':' in object".to_string());
            }
            skip_whitespace(chars);
            let value = parse_value(chars)?;
            map.insert(key, value);

            skip_whitespace(chars);
            match chars.peek() {
                Some(&',') => {
                    chars.next();
                    continue;
                }
                Some(&'}') => {
                    chars.next();
                    break;
                }
                _ => return Err("Expected ',' or '}' in object".to_string()),
            }
        }

        Ok(Value::Object(map))
    }

    fn parse_array(chars: &mut std::iter::Peekable<std::str::Chars>) -> Result<Value, String> {
        chars.next(); // consume '['
        let mut arr = Vec::new();
        skip_whitespace(chars);

        if chars.peek() == Some(&']') {
            chars.next();
            return Ok(Value::Array(arr));
        }

        loop {
            let value = parse_value(chars)?;
            arr.push(value);

            skip_whitespace(chars);
            match chars.peek() {
                Some(&',') => {
                    chars.next();
                    continue;
                }
                Some(&']') => {
                    chars.next();
                    break;
                }
                _ => return Err("Expected ',' or ']' in array".to_string()),
            }
        }

        Ok(Value::Array(arr))
    }

    fn parse_string(chars: &mut std::iter::Peekable<std::str::Chars>) -> Result<String, String> {
        if chars.next() != Some('"') {
            return Err("Expected opening quote".to_string());
        }

        let mut result = String::new();
        let mut escaped = false;

        while let Some(ch) = chars.next() {
            if escaped {
                match ch {
                    '"' | '\\' | '/' => result.push(ch),
                    'b' => result.push('\u{0008}'),
                    'f' => result.push('\u{000C}'),
                    'n' => result.push('\n'),
                    'r' => result.push('\r'),
                    't' => result.push('\t'),
                    _ => result.push(ch),
                }
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == '"' {
                return Ok(result);
            } else {
                result.push(ch);
            }
        }

        Err("Unterminated string".to_string())
    }

    fn parse_number(chars: &mut std::iter::Peekable<std::str::Chars>) -> Result<Value, String> {
        let mut num_str = String::new();

        while let Some(&ch) = chars.peek() {
            if ch == '-' || ch == '+' || ch == '.' || ch == 'e' || ch == 'E' || ch.is_numeric() {
                num_str.push(ch);
                chars.next();
            } else {
                break;
            }
        }

        let num_f64: f64 = num_str.parse().map_err(|_| "Invalid number".to_string())?;
        Ok(Value::Number(num_f64))
    }

    fn parse_bool(chars: &mut std::iter::Peekable<std::str::Chars>) -> Result<Value, String> {
        let mut word = String::new();
        while let Some(&ch) = chars.peek() {
            if ch.is_alphabetic() {
                word.push(ch);
                chars.next();
            } else {
                break;
            }
        }

        match word.as_str() {
            "true" => Ok(Value::Bool(true)),
            "false" => Ok(Value::Bool(false)),
            _ => Err("Invalid boolean".to_string()),
        }
    }

    fn parse_null(chars: &mut std::iter::Peekable<std::str::Chars>) -> Result<Value, String> {
        let mut word = String::new();
        while let Some(&ch) = chars.peek() {
            if ch.is_alphabetic() {
                word.push(ch);
                chars.next();
            } else {
                break;
            }
        }

        if word == "null" {
            Ok(Value::Null)
        } else {
            Err("Invalid null".to_string())
        }
    }
}
