    } else if part.starts_with("average(") {
        let (field, as_name) = extract_field_and_as(part, "average")?;
        if let Some(by_part) = part.split("by").nth(1) {
            for field in by_part.split(',') {
                group_by_fields.push(field.trim().to_string());
            }
        }
