        if let Some(by_part) = part.split("by").nth(1) {
            for field in by_part.split(',') {
                group_by_fields.push(field.trim().to_string());
            }
        }
        aggregations.push(AggregationOp::Max { field, as_name });
    } else if part.starts_with("p") {
        let percentile_str = part.chars().skip(1).take_while(|c| c.is_numeric()).collect::<String>();
        if let Ok(percentile) = percentile_str.parse::<u32>() {
            let prefix = format!("p{}(", percentile);
            if part.starts_with(&prefix) {
                let (field, as_name) = extract_field_and_as(part, &format!("p{}", percentile))?;
                if let Some(by_part) = part.split("by").nth(1) {
                    for field in by_part.split(',') {
                        group_by_fields.push(field.trim().to_string());
                    }
                }
                aggregations.push(AggregationOp::Percentile { field, percentile, as_name });
            }
        }
    } else if part.starts_with("count_distinct(") {
        let (field, as_name) = extract_field_and_as(part, "count_distinct")?;
        if let Some(by_part) = part.split("by").nth(1) {
            for field in by_part.split(',') {
                group_by_fields.push(field.trim().to_string());
            }
        }
        aggregations.push(AggregationOp::CountDistinct { field, as_name });
    }
    Ok(())
}

fn extract_field_and_as(part: &str, op_name: &str) -> Result<(String, Option<String>), String> {
    let open_paren = op_name.to_string() + "(";
    if let Some(start) = part.find(&open_paren) {
        if let Some(end) = part[start..].find(')') {
            let field = part[start + open_paren.len()..start + end].trim().to_string();
            let as_name = extract_as_name(part);
            return Ok((field, as_name));
