                } else {
                    format!("{}.{}", prefix, key)
                };
                flatten_json(val, &new_prefix, map);
            }
        }
        Value::Array(arr) => {
            for (i, val) in arr.iter().enumerate() {
                let new_prefix = format!("{}[{}]", prefix, i);
                flatten_json(val, &new_prefix, map);
            }
        }
        Value::Null => {
            map.insert(prefix.to_string(), Value::Null);
        }
        Value::Bool(b) => {
            map.insert(prefix.to_string(), Value::Bool(*b));
        }
        Value::Number(n) => {
            map.insert(prefix.to_string(), Value::Number(*n));
        }
        Value::String(s) => {
            map.insert(prefix.to_string(), Value::String(s.clone()));
        }
    }
}
