#[derive(Debug, Clone)]
pub enum Filter {
    All,
    MatchAny(String),
    MatchExact(String),
}

impl Filter {
    pub fn matches(&self, line: &str) -> bool {
        match self {
            Filter::All => true,
            Filter::MatchAny(pattern) => {
                let pattern_lower = pattern.to_lowercase();
                let line_lower = line.to_lowercase();
                if pattern_lower.contains('*') {
                    simple_wildcard_match(&line_lower, &pattern_lower)
                } else {
                    line_lower.contains(&pattern_lower)
                }
            }
            Filter::MatchExact(exact) => line.contains(exact),
        }
    }
}

fn simple_wildcard_match(text: &str, pattern: &str) -> bool {
    let mut text_chars = text.chars().peekable();
    let mut pattern_chars = pattern.chars().peekable();

    while let Some(&p_char) = pattern_chars.peek() {
        if p_char == '*' {
            pattern_chars.next();
            if pattern_chars.peek().is_none() {
                return true;
            }
            while text_chars.peek().is_some() {
                if simple_wildcard_match(
                    &text_chars.clone().collect::<String>(),
                    &pattern_chars.clone().collect::<String>(),
                ) {
                    return true;
                }
                text_chars.next();
            }
            return false;
        } else if let Some(&t_char) = text_chars.peek() {
            if t_char != p_char {
                return false;
            }
            text_chars.next();
            pattern_chars.next();
        } else {
            return false;
        }
    }

    text_chars.peek().is_none()
}

pub fn parse_filters(filters: &str) -> Result<Filter, String> {
    if filters.trim() == "*" {
        return Ok(Filter::All);
    }

    if filters.contains('"') {
        let exact = filters.trim_matches('"');
        Ok(Filter::MatchExact(exact.to_string()))
    } else {
        Ok(Filter::MatchAny(filters.to_string()))
    }
}
