use crate::types::{Row, Value, simple_json};
use std::collections::BTreeMap;

#[derive(Debug, Clone)]
pub enum OperatorType {
    Json { from_field: Option<String> },
    Logfmt,
    Parse {
        pattern: String,
        fields: Vec<String>,
    },
    Fields {
        fields: Vec<String>,
    },
}

impl OperatorType {
    pub fn execute(&self, row: &Row) -> Result<Option<Row>, String> {
        match self {
            OperatorType::Json { from_field } => {
                let json_str = if let Some(field) = from_field {
                    row.get(field)
                        .and_then(|v| v.as_str())
                        .ok_or_else(|| format!("Field not found: {}", field))?
                } else {
                    row.get("_raw")
                        .or_else(|| row.values().next())
                        .and_then(|v| v.as_str())
                        .unwrap_or("")
                };

                match simple_json::parse(json_str) {
                    Ok(parsed) => {
                        let mut result = row.clone();
                        flatten_json(&parsed, "", &mut result);
                        Ok(Some(result))
                    }
                    Err(_) => Ok(None),
                }
            }
            OperatorType::Logfmt => {
                let line = row
                    .get("_raw")
                    .or_else(|| row.values().next())
                    .and_then(|v| v.as_str())
                    .unwrap_or("");

                let mut result = row.clone();
                for part in line.split_whitespace() {
                    if let Some((key, val)) = part.split_once('=') {
                        result.insert(key.to_string(), Value::String(val.to_string()));
                    }
                }
                Ok(Some(result))
            }
            OperatorType::Parse { pattern, fields } => {
                let line = row
                    .get("_raw")
                    .or_else(|| row.values().next())
                    .and_then(|v| v.as_str())
                    .unwrap_or("");

                if let Some(parsed_row) = parse_line(line, pattern, fields) {
                    let mut result = row.clone();
                    for (key, val) in parsed_row {
                        result.insert(key, val);
                    }
                    Ok(Some(result))
                } else {
                    Ok(None)
                }
            }
            OperatorType::Fields { fields } => {
                let mut result = BTreeMap::new();
                for field in fields {
                    if let Some(val) = row.get(field) {
                        result.insert(field.clone(), val.clone());
                    }
                }
                Ok(Some(result))
            }
        }
    }
}

fn parse_line(line: &str, pattern: &str, fields: &[String]) -> Option<BTreeMap<String, Value>> {
    let pattern_parts: Vec<&str> = pattern.split('*').collect();

    if pattern_parts.len() != fields.len() + 1 {
        return None;
    }

    let mut result = BTreeMap::new();
    let mut line_pos = 0;

    for (i, &part) in pattern_parts.iter().enumerate() {
        if i == 0 {
            if !part.is_empty() {
                if let Some(pos) = line[line_pos..].find(part) {
                    line_pos += pos + part.len();
                } else {
                    return None;
                }
            }
        } else if i == pattern_parts.len() - 1 {
            if !part.is_empty() {
