use crate::aggregator::{AggregationOp, AggregationState, AggregationMap};
use crate::filter::Filter;
use crate::operators::OperatorType;
use crate::output::OutputFormatter;
use crate::types::{Row, Value};
use std::collections::{BTreeMap, HashMap};
use std::io::BufRead;

pub struct Query {
    pub filters: Filter,
    pub operators: Vec<OperatorType>,
    pub aggregations: Vec<AggregationOp>,
    pub group_by_fields: Vec<String>,
    pub sort_field: Option<String>,
    pub sort_desc: bool,
}

impl Query {
    pub fn parse(query_str: &str) -> Result<Self, String> {
        let parts: Vec<&str> = query_str.split('|').collect();
        if parts.is_empty() {
            return Err("Empty query".to_string());
        }

        let filters = crate::filter::parse_filters(parts[0])?;
        let mut operators = Vec::new();
        let mut aggregations = Vec::new();
        let mut group_by_fields = Vec::new();
        let mut sort_field = None;
        let mut sort_desc = false;

        for part in &parts[1..] {
            let trimmed = part.trim();
            if trimmed.starts_with("json") {
                operators.push(OperatorType::Json { from_field: None });
            } else if trimmed.starts_with("logfmt") {
                operators.push(OperatorType::Logfmt);
            } else if trimmed.starts_with("parse") {
                if let Ok(op) = parse_parse_operator(trimmed) {
                    operators.push(op);
                }
            } else if trimmed.starts_with("fields") {
                if let Ok(op) = parse_fields_operator(trimmed) {
                    operators.push(op);
                }
            } else if trimmed.starts_with("count") {
                parse_aggregations(trimmed, &mut aggregations, &mut group_by_fields)?;
            } else if trimmed.starts_with("sum") {
                parse_aggregations(trimmed, &mut aggregations, &mut group_by_fields)?;
            } else if trimmed.starts_with("average") {
                parse_aggregations(trimmed, &mut aggregations, &mut group_by_fields)?;
            } else if trimmed.starts_with("min") {
                parse_aggregations(trimmed, &mut aggregations, &mut group_by_fields)?;
            } else if trimmed.starts_with("max") {
                parse_aggregations(trimmed, &mut aggregations, &mut group_by_fields)?;
            } else if trimmed.starts_with("p") && trimmed.len() > 1 && trimmed.chars().nth(1).map(|c| c.is_numeric()).unwrap_or(false) {
                parse_aggregations(trimmed, &mut aggregations, &mut group_by_fields)?;
            } else if trimmed.starts_with("count_distinct") {
                parse_aggregations(trimmed, &mut aggregations, &mut group_by_fields)?;
            } else if trimmed.starts_with("sort") {
                parse_sort(trimmed, &mut sort_field, &mut sort_desc)?;
            }
        }

        Ok(Query {
            filters,
            operators,
            aggregations,
            group_by_fields,
            sort_field,
            sort_desc,
        })
    }

    pub fn execute(&self, reader: Box<dyn BufRead>, output_format: Option<&str>) -> Result<(), String> {
        let formatter = OutputFormatter::new(output_format);

        if self.aggregations.is_empty() {
            for line in reader.lines() {
                let line = line.map_err(|e| e.to_string())?;
                if !self.filters.matches(&line) {
                    continue;
                }

                let mut row = BTreeMap::new();
                row.insert("_raw".to_string(), Value::String(line));

                if let Ok(Some(processed)) = self.apply_operators(&row) {
                    formatter.output_row(&processed).ok();
                }
            }
        } else {
            let mut agg_map: AggregationMap = HashMap::new();

            for line in reader.lines() {
                let line = line.map_err(|e| e.to_string())?;
                if !self.filters.matches(&line) {
                    continue;
                }

                let mut row = BTreeMap::new();
                row.insert("_raw".to_string(), Value::String(line));

                if let Ok(Some(processed)) = self.apply_operators(&row) {
                    self.aggregate(&processed, &mut agg_map).ok();
                }
            }

            let mut results = Vec::new();
            for (group_key, agg_values) in agg_map.iter() {
                let mut output_row = BTreeMap::new();
                for (field, value) in group_key {
                    if field != "_group" {
                        output_row.insert(field.clone(), value.clone());
                    }
                }
                for agg_op in &self.aggregations {
                    if let Some(agg_state) = agg_values.get(&agg_op.output_name()) {
                        output_row.insert(agg_op.output_name(), agg_state.compute(agg_op));
                    }
                }
                results.push(output_row);
            }

            results.sort_by(|a, b| {
                for field in &self.group_by_fields {
                    let a_val = a.get(field).unwrap_or(&Value::Null);
                    let b_val = b.get(field).unwrap_or(&Value::Null);
                    let cmp = compare_values(a_val, b_val);
                    if cmp != std::cmp::Ordering::Equal {
                        return cmp;
                    }
                }
                std::cmp::Ordering::Equal
            });

            if let Some(sort_by) = &self.sort_field {
                results.sort_by(|a, b| {
                    let a_val = a.get(sort_by).unwrap_or(&Value::Null);
                    let b_val = b.get(sort_by).unwrap_or(&Value::Null);
                    let cmp = compare_values(a_val, b_val);
                    if self.sort_desc {
                        cmp.reverse()
                    } else {
                        cmp
                    }
                });
            }

            formatter.output_rows(&results).ok();
        }

        Ok(())
    }

    fn apply_operators(&self, row: &Row) -> Result<Option<Row>, String> {
        let mut current = row.clone();

        for op in &self.operators {
            match op.execute(&current)? {
                Some(r) => current = r,
                None => return Ok(None),
            }
        }

        Ok(Some(current))
    }

    fn aggregate(&self, row: &Row, agg_map: &mut AggregationMap) -> Result<(), String> {
        let mut group_key = Vec::new();
        for field in &self.group_by_fields {
            let value = row.get(field).cloned().unwrap_or(Value::Null);
            group_key.push((field.clone(), value));
        }

        if group_key.is_empty() {
            group_key.push(("_group".to_string(), Value::String("_all".to_string())));
        }

        let agg_entry = agg_map.entry(group_key).or_insert_with(HashMap::new);

        for agg_op in &self.aggregations {
            let state = agg_entry.entry(agg_op.output_name()).or_insert_with(AggregationState::new);

            match agg_op {
                AggregationOp::Count { .. } => {
                    state.update(Some(1.0), None);
                }
                AggregationOp::Sum { field, .. } => {
                    let value = row.get(field).and_then(|v| v.as_f64());
                    state.update(value, None);
                }
                AggregationOp::Average { field, .. } => {
                    let value = row.get(field).and_then(|v| v.as_f64());
                    state.update(value, None);
                }
                AggregationOp::Min { field, .. } => {
                    let value = row.get(field).and_then(|v| v.as_f64());
                    state.update(value, None);
                }
                AggregationOp::Max { field, .. } => {
                    let value = row.get(field).and_then(|v| v.as_f64());
                    state.update(value, None);
                }
                AggregationOp::Percentile { field, .. } => {
                    let value = row.get(field).and_then(|v| v.as_f64());
                    state.update(value, None);
                }
                AggregationOp::CountDistinct { field, .. } => {
                    let value = row.get(field).map(|v| v.to_string());
                    state.update(None, value);
                }
            }
        }

        Ok(())
    }
}

fn parse_parse_operator(part: &str) -> Result<OperatorType, String> {
    if let Some(pattern_start) = part.find('"') {
        if let Some(pattern_end) = part[pattern_start + 1..].find('"') {
            let pattern = part[pattern_start + 1..pattern_start + 1 + pattern_end].to_string();
            if let Some(as_pos) = part.find("as") {
                let after_as = part[as_pos + 2..].trim();
                let fields: Vec<String> = after_as.split(',').map(|s| s.trim().to_string()).collect();
                return Ok(OperatorType::Parse { pattern, fields });
            }
        }
    }
    Err("Invalid parse operator".to_string())
}

fn parse_fields_operator(part: &str) -> Result<OperatorType, String> {
    let after_fields = part.strip_prefix("fields").unwrap_or(part).trim();
    let fields: Vec<String> = after_fields.split(',').map(|s| s.trim().to_string()).collect();
    Ok(OperatorType::Fields { fields })
}

fn parse_aggregations(
    part: &str,
    aggregations: &mut Vec<AggregationOp>,
    group_by_fields: &mut Vec<String>,
) -> Result<(), String> {
    if part.starts_with("count") && !part.starts_with("count_distinct") {
        let as_name = extract_as_name(part);
        if let Some(by_part) = part.split("by").nth(1) {
            for field in by_part.split(',') {
                group_by_fields.push(field.trim().to_string());
            }
        }
        aggregations.push(AggregationOp::Count { as_name });
    } else if part.starts_with("sum(") {
        let (field, as_name) = extract_field_and_as(part, "sum")?;
        if let Some(by_part) = part.split("by").nth(1) {
            for field in by_part.split(',') {
                group_by_fields.push(field.trim().to_string());
            }
        }
        aggregations.push(AggregationOp::Sum { field, as_name });
    } else if part.starts_with("average(") {
        let (field, as_name) = extract_field_and_as(part, "average")?;
        if let Some(by_part) = part.split("by").nth(1) {
            for field in by_part.split(',') {
                group_by_fields.push(field.trim().to_string());
            }
        }
        aggregations.push(AggregationOp::Average { field, as_name });
    } else if part.starts_with("min(") {
        let (field, as_name) = extract_field_and_as(part, "min")?;
        if let Some(by_part) = part.split("by").nth(1) {
            for field in by_part.split(',') {
                group_by_fields.push(field.trim().to_string());
            }
        }
        aggregations.push(AggregationOp::Min { field, as_name });
    } else if part.starts_with("max(") {
        let (field, as_name) = extract_field_and_as(part, "max")?;
        if let Some(by_part) = part.split("by").nth(1) {
            for field in by_part.split(',') {
                group_by_fields.push(field.trim().to_string());
            }
        }
        aggregations.push(AggregationOp::Max { field, as_name });
    } else if part.starts_with("p") {
        let percentile_str = part.chars().skip(1).take_while(|c| c.is_numeric()).collect::<String>();
        if let Ok(percentile) = percentile_str.parse::<u32>() {
            let prefix = format!("p{}(", percentile);
            if part.starts_with(&prefix) {
                let (field, as_name) = extract_field_and_as(part, &format!("p{}", percentile))?;
                if let Some(by_part) = part.split("by").nth(1) {
                    for field in by_part.split(',') {
                        group_by_fields.push(field.trim().to_string());
